import heapq

def shortest_path(edges, start, end):
    """
    Compute the shortest path between two nodes in a directed weighted graph.

    Args:
        edges: List of (from_node, to_node, weight) tuples
        start: Starting node
        end: Target node

    Returns:
        Tuple of (distance, path) where distance is shortest total weight and 
        path is ordered list of nodes. Returns (None, None) if no path exists.

    Raises:
        ValueError: If any edge has negative weight.
    """
    # Check for negative weights
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight is not allowed")

    # Handle same start and end
    if start == end:
        return (0, [start])

    # Build graph using adjacency list with minimum edge weights
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = {}
        current_weight = graph[from_node].get(to_node, float('inf'))
        graph[from_node][to_node] = min(current_weight, weight)

    # Check that start node has outgoing edges
    if start not in graph or len(graph[start]) == 0:
        return (None, None)

    # Initialize distances and predecessor tracking
    all_nodes = set()
    for u in graph:
        for v in graph[u]:
            all_nodes.add(u)
            all_nodes.add(v)

    distances = {node: float('inf') for node in all_nodes}
    previous = {}
    distances[start] = 0
    pq = [(0, start)]
    visited = set()

    # Dijkstra's algorithm
    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node in visited or current_dist > distances[current_node]:
            continue
        visited.add(current_node)

        for neighbor, weight in graph.get(current_node, {}).items():
            new_dist = current_dist + weight
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                previous[neighbor] = current_node
                heapq.heappush(pq, (new_dist, neighbor))

    # Check if end is reachable
    if distances[end] == float('inf'):
        return (None, None)

    # Reconstruct the path
    path = []
    node = end
    while node != start:
        if node not in previous:
            return (None, None)  # Path cannot be reconstructed
        path.append(node)
        node = previous[node]
    path.append(start)
    path.reverse()

    return (distances[end], path)
